#define CUT_COUNT 32
#define BEAT_COUNT 201
#define CHOICE_COUNT 22
#define STORY_FLAGS 115
#define STORY_WORDS 4   /* a hundred and twenty-eight, in four words */
#define BEAT_SAY     0
#define BEAT_WAIT    1
#define BEAT_SHAKE   2
#define BEAT_FLASH   3
#define BEAT_SPAWN   4
#define BEAT_WALK    5
#define BEAT_FACE    6
#define BEAT_DESPAWN 7
#define BEAT_SKY     8
