typedef struct { u8 x, y, to, tx, ty; } Warp;
typedef struct { u8 x, y; const char *text; } Sign;
typedef struct { u16 duellist; u8 bank; } Ambush;
typedef struct { u8 beast, level; } Wild;
typedef struct { u8 x, y, ware; u16 gold; } Chest;
typedef struct {
  u8 x, y, dir, bank, roams, heals, fights, trade, sight, challenges, sails, holds, weds, ranges, evening, gate, builds;
  u16 duellist;
  const char *name, *line;
} Npc;
typedef struct {
  const char *name;
  u8 w, h;
  u16 tileCount;
  const u32 *tiles;
  const u16 *entries;
  const u8  *solid;
  const u8  *cover;     /* where something can be hiding */
  const u8  *ledge;     /* a drop you can take but not climb */
  const u8  *counter;   /* solid, but you can speak across it */
  const u8  *water;     /* solid on foot; the only road under sail */
  u8 frost;             /* whether the cover here is under snow */
  u8 cold;              /* how far north, 0 Dorne to 5 beyond the Wall */
  u8 tune;              /* what plays here */
  u8 scene;             /* which sky a duel fought here is fought under */
  const u16 *residents; u8 residentCount;
  const Warp *warps; u8 warpCount;
  const Sign *signs; u8 signCount;
  const Npc  *npcs;  u8 npcCount;
  const Ambush *ambushes; u8 ambushCount;
  const Wild *wilds; u8 wildCount;
  const Chest *chests; u8 chestCount;
  const Lane *lanes; u8 laneCount;   /* who is out on this water */
  u8 sea;               /* the rules are the other way up here */
  u8 nest;              /* the egg that is found here, or 255 */
  u8 seat;              /* what this hall costs in hundreds, 0 not for sale */
  u8 courtX, courtY;    /* where the chair is, 255 if there is no chair */
  u8 holder;            /* which of the nine holds this ground, 255 none */
} Map;

